def english_place(value):
    value = clean_space(value)
    key = folded(value)
    if key in PLACE_OVERRIDES:
        return PLACE_OVERRIDES[key]
    for prefix, suffix in (
        ("ΣΥΝΟΙΚΙΣΜΟΣ ", " Refugee Settlement"),
        ("ΑΥΤΟΣΤΕΓΑΣΙΣ ", " Self-housing Settlement"),
        ("ΟΙΚΙΣΜΟΣ ", " Settlement"),
    ):
        if key.startswith(prefix):
            place_key = key[len(prefix):]
            place = PLACE_OVERRIDES.get(place_key, transliterate(place_key))
            return place + suffix
    return transliterate(value)


