def person_phrase(value):
    value = folded(value).strip()
    value = re.sub(r"\s*,\s*", " ", value)
    if value in PERSON_PHRASES:
        return PERSON_PHRASES[value]
    return " ".join(
        PERSON_WORDS.get(word, transliterate(word))
        for word in value.split()
    )


