def dedication_parts(value):
    value = clean_space(value)
    match = re.match(r"^(.*?)(?:\s*\(([^()]*)\))?$", value)
    base = folded(match.group(1)).strip(" ,")
    qualifier = match.group(2) if match else None
    base = base.split(", ΠΑΡΑ ", 1)[0]
    if base in FEASTS:
        english = FEASTS[base]
    else:
        rules = (
            ("ΑΓΙΟΥ ", "Saint "), ("ΑΓΙΑΣ ", "Saint "),
            ("ΑΓΙΩΝ ", "Saints "), ("ΟΣΙΑΣ ", "Venerable "),
            ("ΟΣΙΩΝ ", "Venerable "), ("ΑΠΟΣΤΟΛΟΥ ", "Apostle "),
            ("ΑΠΟΣΤΟΛΩΝ ", "Apostles "),
            ("ΑΡΧΑΓΓΕΛΟΥ ", "Archangel "),
            ("ΠΡΟΦΗΤΟΥ ", "Prophet "),
        )
        english = None
        for prefix, translated in rules:
            if base.startswith(prefix):
                english = translated + person_phrase(base[len(prefix):])
                break
        if english is None and base.startswith("ΠΑΝΑΓΙΑΣ"):
            rest = base[len("ΠΑΝΑΓΙΑΣ"):].strip()
            epithet = PANAGIA_EPITHETS.get(rest, transliterate(rest))
            english = "Panagia" + ((" " + epithet) if rest else "")
        if english is None and base.startswith("ΠΑΝΑΓΙΑ"):
            rest = base[len("ΠΑΝΑΓΙΑ"):].strip()
            epithet = PANAGIA_EPITHETS.get(rest, transliterate(rest))
            english = "Panagia" + ((" " + epithet) if rest else "")
        if english is None:
            english = transliterate(base)
    return clean_space(english), qualifier


