def slug(value):
    value = transliterate(value).lower()
    return re.sub(r"[^a-z0-9]+", "-", value).strip("-") or "body"


def rank_for(designation, dedication):
    source = folded(designation + " " + dedication)
    if "ΠΑΡΕΚΚΛ" in source:
        return "Chapel"
    if "ΜΟΝΗ" in source:
        return "Monastery"
    if "ΚΑΘΕΔΡΙΚ" in source:
        return "Cathedral"
    if "ΜΗΤΡΟΠΟΛΙΤ" in source:
        return "Metropolitan Church"
    if "ΠΡΟΣΚΥΝΗΜΑΤ" in source:
        return "Pilgrimage Church"
    return "Church"


RANK_OVERRIDES = {
    ("cy-constantia", 3): "Metochion",
}


def split_dedications(value):
    normalized = folded(value)
    marker = " ΚΑΙ ΙΕΡΟΣ ΝΑΟΣ "
    if marker not in normalized:
        return [value]
    left, right = normalized.split(marker, 1)
    return [left, right]


def source_rows():
    rows = []
    ids = set()
    for parent, number, place, dedication, designation in RAW:
        if (parent, number) == ("cy-limassol", 28):
            # Antioch's own current directory identifies this church as its
            # Limassol metochion. Keep the existing stable key but publish the
            # body under the Church that expressly lists it among its own.
            continue
        parts = split_dedications(dedication)
        for part_number, part in enumerate(parts, 1):
            key = (parent, number)
            rank = RANK_OVERRIDES.get(key, rank_for(designation, part))
            location = LOCATION_OVERRIDES.get(key, english_place(place))
            dedication_en, qualifier = dedication_parts(part)
            qualifier_key = folded(qualifier or "")
            if qualifier and not any(term in qualifier_key for term in (
                    "ΜΗΤΡΟΠΟΛΙΤ", "ΚΑΘΕΔΡΙΚ", "ΔΙΑ ΤΟΥΣ")):
                if "ΚΟΙΜΗΤΗΡΙ" in qualifier_key:
                    location = "%s Cemetery" % english_place(place)
                elif "ΣΥΝΟΙΚΙΣΜ" in qualifier_key or "ΟΙΚΙΣΜ" in qualifier_key:
                    location = english_place(qualifier)
                elif key not in LOCATION_OVERRIDES:
                    location = english_place(qualifier)
            part_key = (parent, number, part_number)
            if part_key in SPECIAL_PART_NAMES:
                name = SPECIAL_PART_NAMES[part_key]
            elif key in SPECIAL_NAMES and len(parts) == 1:
                name = SPECIAL_NAMES[key]
            else:
                noun = {
                    "Church": "Church", "Chapel": "Chapel",
                    "Cathedral": "Cathedral",
                    "Metropolitan Church": "Metropolitan Church",
                    "Pilgrimage Church": "Pilgrimage Church",
                    "Monastery": "Monastery",
                }[rank]
                preposition = "at" if location.startswith("near ") else "in"
                name = "%s %s %s %s" % (
                    dedication_en, noun, preposition, location,
                )
            base_id = "cy-%s-%03d-%s" % (
                parent[3:] if parent.startswith("cy-") else parent,
                number, slug(part),
            )
            if len(parts) > 1:
                base_id += "-%d" % part_number
            if base_id in ids:
                raise ValueError("duplicate generated id: %s" % base_id)
            ids.add(base_id)
            local_noun = clean_space(designation)
            local = "%s %s, %s" % (local_noun, clean_space(part), clean_space(place))
            rows.append({
                "id": base_id,
                "parent": parent,
                "country": "CY",
                "kind": "monastery" if rank == "Monastery" else "parish",
                "rank": rank,
                "local": local,
                "name": clean_space(name),
                "sources": [CYPRUS_DIRECTORY],
            })
    return rows


def manual(row_id, parent, local, name, rank="Church", sources=None,
           kind=None, address=None):
    item = {
        "id": row_id, "parent": parent, "country": "CY",
        "kind": kind or ("monastery" if rank in {
            "Monastery", "Skete", "Hesychasterion"
        } else "parish"),
        "rank": rank, "local": local, "name": name,
        "sources": sources or [CYPRUS_DIRECTORY],
    }
    if address:
        item["address"] = address
    return item


